func TestListsSettingsUpdateSortOrderCommandRegistered(t *testing.T) {
	t.Parallel()

	cmd := newListsSettingsUpdateSortOrderCmd(&rootFlags{})
	if cmd.Name() != "update-sort-order" {
		t.Fatalf("command name = %q, want update-sort-order", cmd.Name())
	}

	apply, err := cmd.Flags().GetBool("apply")
	if err != nil {
		t.Fatalf("missing --apply flag: %v", err)
	}
	if apply {
		t.Fatal("--apply defaults to true; the command must preview by default")
	}
	for _, name := range []string{"name", "sort-order", "stdin"} {
		if cmd.Flags().Lookup(name) == nil {
			t.Fatalf("missing --%s flag", name)
		}
	}

	settings := newListsSettingsCmd(&rootFlags{})
	var found bool
	for _, sub := range settings.Commands() {
		if sub.Name() == "update-sort-order" {
			found = true
		}
	}
	if !found {
		t.Fatal("lists settings does not register update-sort-order")
	}
}

