func TestFindListSortOrderTargetByExactName(t *testing.T) {
	t.Parallel()

	data := liveUserDataForSortOrderTests()

	got, err := findListSortOrderTargetByExactName(data, "dinner")
	if err != nil {
		t.Fatalf("findListSortOrderTargetByExactName returned error: %v", err)
	}
	if got.GetIdentifier() != "list-2" {
		t.Fatalf("resolved ID = %q, want list-2", got.GetIdentifier())
	}

	// Prefix/contains matches must not count as an exact name match.
	if _, err := findListSortOrderTargetByExactName(data, "Gro"); err == nil {
		t.Fatal("expected rejection for a prefix-only name match")
	}
	if _, err := findListSortOrderTargetByExactName(data, "no such list"); err == nil {
		t.Fatal("expected rejection for a missing list name")
	}

	duplicate := &pb.PBUserDataResponse{
		ShoppingListsResponse: &pb.ShoppingListsResponse{
			ModifiedLists: []*pb.ShoppingList{
				{Identifier: "list-a", Name: "Groceries"},
				{Identifier: "list-b", Name: "GROCERIES"},
			},
		},
	}
	if _, err := findListSortOrderTargetByExactName(duplicate, "Groceries"); err == nil || !strings.Contains(err.Error(), "ambiguous") {
		t.Fatalf("expected ambiguity rejection, got %v", err)
	}
}

